CREATE INDEX jobs_fetch_problem_recovery ON jobs(id) WHERE kind='fetch' AND item IS NOT NULL AND item<>'' AND problem_code IS NOT NULL AND problem_code<>'' AND problem_code NOT LIKE 'source-%' AND problem_code NOT IN ('codex-choice','ai-permission','youtube-admission','processor-config','identity-unconfirmed','profile_not_configured','profile_unavailable','account_identity_mismatch','work-fetch');
CREATE INDEX reader_fetch_problem_identity ON reader_problems ((body::jsonb->>'fetch_job_identity')) WHERE finished IS NULL AND body::jsonb->>'operation'='producer:fetch';
CREATE INDEX reader_fetch_problem_recovery ON reader_problems(created,id) WHERE finished IS NULL AND identity LIKE 'job:%' AND body::jsonb->>'operation' IN ('producer:fetch','producer:status') AND body::jsonb->>'code' IS NOT NULL AND body::jsonb->>'code'<>'' AND body::jsonb->>'code' NOT LIKE 'source-%' AND body::jsonb->>'code' NOT IN ('codex-choice','ai-permission','youtube-admission','processor-config','identity-unconfirmed','profile_not_configured','profile_unavailable','account_identity_mismatch','work-fetch');
DROP INDEX jobs_unmanaged_problems;
CREATE INDEX jobs_unmanaged_problems ON jobs(kind,item) WHERE (kind IS DISTINCT FROM 'read' OR problem_code='processor-config') AND (kind IS DISTINCT FROM 'discover' OR problem_code='processor-config') AND NOT (kind IN ('delete','feed-delete') AND coalesce(nullif(problem_code,''),'work-'||kind) IN ('delete','feed-delete','work-delete','work-feed-delete')) AND NOT (kind IS NOT DISTINCT FROM 'fetch' AND item IS NOT NULL AND item<>'' AND problem_code IS NOT NULL AND problem_code<>'' AND problem_code NOT LIKE 'source-%' AND problem_code NOT IN ('codex-choice','ai-permission','youtube-admission','processor-config','identity-unconfirmed','profile_not_configured','profile_unavailable','account_identity_mismatch','work-fetch')) AND (problem_code IS NOT NULL OR error IS NOT NULL);
